using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using BepInEx.Configuration;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class ConfigProfiles {
 internal sealed record Plan(string Name,Dictionary<string,string> Settings);
 static List<Plan> plans=new();static bool corrupt;static string name="",status="";static Vector2 scroll;static int current=-1;
 static string FilePath=>Path.Combine(BepInEx.Paths.PluginPath,"LocalSpt5ESP","config-profiles.json");
 internal static void Initialize(){try{plans=PresetStorage.Load<Plan>(FilePath);if(plans.Count==0&&!File.Exists(FilePath)){var normal=Snapshot();Set(normal,"1. ESP","People","false");Set(normal,"1. ESP","Items","false");Set(normal,"2. God mode","Enabled","false");Set(normal,"4. AI ignore","Enabled","false");Set(normal,"8. Aim assist","Mode","Off");Set(normal,"10. Recoil assist","No recoil","false");Set(normal,"20. Movement","Unlimited leg stamina","false");Set(normal,"20. Movement","Unlimited arm stamina","false");var loot=new Dictionary<string,string>(normal);Set(loot,"1. ESP","Items","true");Set(loot,"27. 搜刮筛选","Scan raid loot","true");var training=new Dictionary<string,string>(normal);Set(training,"28. 武器便利","Infinite ammunition","true");Set(training,"28. 武器便利","No malfunction","true");Set(training,"2. God mode","Enabled","true");plans=new(){new("正常游玩",normal),new("搜刮",loot),new("练枪",training)};PresetStorage.Save(FilePath,plans);}}catch(Exception e){corrupt=true;status="方案文件读取失败，原文件已保留："+e.Message;}}
 static string Key(ConfigEntryBase entry)=>entry.Definition.Section+"\n"+entry.Definition.Key;
 static Dictionary<string,string> Snapshot()=>Plugin.Self.Config.ToDictionary(pair=>Key(pair.Value),pair=>pair.Value.GetSerializedValue());
 static void Set(Dictionary<string,string> settings,string section,string key,string value)=>settings[section+"\n"+key]=value;
 static void Apply(Plan plan){var entries=Plugin.Self.Config.ToDictionary(pair=>Key(pair.Value),pair=>pair.Value);var changes=new List<(ConfigEntryBase Entry,object Value,object Old)>();foreach(var pair in plan.Settings){if(!entries.TryGetValue(pair.Key,out var entry))continue;var value=TomlTypeConverter.ConvertToValue(pair.Value,entry.SettingType);if(value==null)throw new ArgumentException("方案含无效值。");var bounds=entry.Description.AcceptableValues;if(bounds!=null&&!bounds.IsValid(value))throw new ArgumentException("方案参数超出范围："+entry.Definition.Key);changes.Add((entry,value,entry.BoxedValue));}bool save=Plugin.Self.Config.SaveOnConfigSet;Plugin.Self.Config.SaveOnConfigSet=false;try{foreach(var change in changes)change.Entry.BoxedValue=change.Value;Plugin.Self.Config.Save();InterfaceMenu.ClearDrafts();status="已套用："+plan.Name;}catch{foreach(var change in changes)change.Entry.BoxedValue=change.Old;throw;}finally{Plugin.Self.Config.SaveOnConfigSet=save;}}
 internal static void Keys(){if(!Hotkeys.Pressed(KeyCode.F2)||plans.Count==0||corrupt)return;try{current=(current+1)%plans.Count;Apply(plans[current]);}catch(Exception e){status=e.Message;Plugin.Self.Error(e);}}
 internal static void Draw(Rect rect){InterfaceMenu.Label(new Rect(rect.x,rect.y,rect.width,30),"配置方案",InterfaceMenu.Accent,19);InterfaceMenu.Paragraph(new Rect(rect.x,rect.y+38,rect.width,48),"保存全部辅助设置与布局，点击套用或按 Ctrl+F2 循环切换。修改现有方案时填写相同名称。",null,12);name=InterfaceMenu.Field(new Rect(rect.x,rect.y+96,rect.width-170,31),name);if(InterfaceMenu.Button(new Rect(rect.xMax-158,rect.y+96,158,31),"保存当前设置"))try{if(corrupt)throw new ArgumentException("请先修复方案文件，防止覆盖。");string title=name.Trim();if(title.Length is <1 or >80)throw new ArgumentException("请输入 1～80 字的方案名称。");var updated=plans.Where(p=>!p.Name.Equals(title,StringComparison.OrdinalIgnoreCase)).Append(new Plan(title,Snapshot())).ToList();PresetStorage.Save(FilePath,updated);plans=updated;status="已保存："+title;}catch(Exception e){status=e.Message;}
  var hotkeys=Plugin.Self.Config.Where(p=>p.Value.BoxedValue is KeyCode key&&key!=KeyCode.None).GroupBy(p=>(KeyCode)p.Value.BoxedValue).Where(g=>g.Count()>1).Select(g=>g.Key+"："+string.Join(" / ",g.Select(p=>p.Value.Description.Tags.OfType<CnConfig.ConfigurationManagerAttributes>().FirstOrDefault()?.DispName??p.Key.Key))).ToList();
  var view=new Rect(rect.x,rect.y+144,rect.width,Math.Max(60,rect.height-265));scroll=GUI.BeginScrollView(view,scroll,new Rect(0,0,view.width-18,Math.Max(60,plans.Count*67)));Plan? remove=null;for(int i=0;i<plans.Count;i++){var plan=plans[i];float y=i*67;InterfaceMenu.Surface(new Rect(0,y,view.width-24,57),new Color(1,1,1,.035f),8);InterfaceMenu.Label(new Rect(12,y+10,view.width-245,32),plan.Name);if(InterfaceMenu.Button(new Rect(view.width-222,y+12,90,30),"套用"))try{Apply(plan);}catch(Exception e){status=e.Message;}if(InterfaceMenu.Button(new Rect(view.width-122,y+12,90,30),"删除"))remove=plan;}GUI.EndScrollView();if(remove!=null)try{var updated=plans.Where(p=>p!=remove).ToList();PresetStorage.Save(FilePath,updated);plans=updated;status="方案已删除";}catch(Exception e){status=e.Message;}
  InterfaceMenu.Paragraph(new Rect(rect.x,rect.yMax-106,rect.width,96),status+"\n按键复用提醒（部分为共用窗口键）："+(hotkeys.Count==0?"未发现复用":string.Join("；",hotkeys.Take(4))),null,12);
 }
}
